    content: `
Física costuma ser o "medo" de muitos candidatos no ENEM. Mas o segredo é simples: o ENEM não quer que você calcule — quer que você entenda os conceitos e aplique em contexto.

## Por que Física no ENEM é Diferente

Em provas tradicionais de vestibular, Física = calcular. No ENEM, Física = interpretar uma situação e identificar qual conceito físico explica o fenômeno. As fórmulas estão disponíveis no enunciado — o que o ENEM testa é se você sabe *como usá-las*.

## Os 10 Temas Mais Cobrados

### 1. Eletricidade e Eletromagnetismo (10–12% das questões de Física)

- Circuitos em série e paralelo: resistência equivalente, corrente, tensão
- Lei de Ohm: relação V = R·I em contextos práticos
- Potência elétrica: consumo de energia, conta de luz
- Campo magnético: força sobre cargas e condutores

**Dica:** Questões de eletricidade frequentemente trazem tabelas de componentes elétricos. Aprenda a calcular resistência equivalente em circuitos mistos.

### 2. Termodinâmica (8–10% das questões de Física)

- Leis da termodinâmica (especialmente 1ª e 2ª lei)
- Máquinas térmicas: eficiência, trabalho, calor
- Dilatação: linear, superficial, volumétrica

### 3. Ondulatória e Acústica (8–10%)

- Velocidade, frequência e comprimento de onda
- Efeito Doppler: fonte em movimento
- Reflexão, refração, difração

### 4. Ótica (7–9%)

- Reflexão: lei da reflexão, espelhos planos e curvos
- Refração: lei de Snell, índice de refração
- Lentes: convergentes e divergentes, formação de imagem

### 5. Mecânica — Dinâmica (7–9%)

- Segunda lei de Newton: F = ma em situações variadas
- Trabalho e energia: energia cinética, potencial, conservação
- Impulso e quantidade de movimento

### 6. Mecânica — Cinemática (6–8%)

- Movimento uniforme: velocidade, posição, tempo
- Movimento uniformemente variado: aceleração, queda livre
- Gráficos de posição e velocidade × tempo

### 7. Gravitação (4–6%)

- Lei de gravitação universal
- Satélites: velocidade orbital, período

### 8. Hidrostática (4–5%)

- Pressão: P = F/A
- Princípio de Arquimedes: empuxo
- Vasos comunicantes

### 9. Calorimetria (4–5%)

- Calor sensível e latente
- Propagação de calor: condução, convecção, irradiação

### 10. Física Moderna e Quântica (3–5%)

- Dualidade onda-partícula
- Efeito fotoelétrico
- Radioatividade: tipos de radiação, meia-vida

## Como Estudar Física para o ENEM

1. **Não tente decorar fórmulas** — o enunciado as fornece quando necessário
2. **Entenda o conceito primeiro** — o que causa o fenômeno físico
3. **Resolva questões do ENEM** (não de vestibulares regionais)
4. **Quando errar, pergunte "por quê?"** — não apenas qual a resposta correta

---

## Pratique Física com Questões do ENEM

Resolva questões de Física do ENEM de 2009 a 2024 no ENEM Pro. A IA explica o raciocínio físico de cada questão.
    `,
